2-// Glossary RAG client for models running inside harness containers.
3-// Zero dependencies (Node >= 18 for fetch). Talks to the host's RAG server
4-// (swarm/rag/server.py) at $RAG_URL, else http://host.docker.internal:$RAG_PORT.
5-//
6-//   node /kit/rag.mjs retrieve [--file /trajectory.txt]   steps 1-4: needs + candidates + records
7-//   node /kit/rag.mjs search "<need 1>" ["<need 2>" ...] [--kind constraint]   one call, several needs
8-//   node /kit/rag.mjs widen  "<need text>" [--kind ...]      step 6: broad search for an unresolved need
9-//   node /kit/rag.mjs entry  <symbol> [<symbol> ...]        compact records + their rules and dependencies;
10-//                                                            a value group also lists its slots, and
11-//                                                            `entry currency::ZAR` says whether that key is valid
12://   node /kit/rag.mjs check  --translation /output/translation.md [--needs /needs.json]   step 5
13-//   node /kit/rag.mjs needs  [--file ...]                   step 1 only
14-//   node /kit/rag.mjs health
15-//
16-// Output is the rendered text a model reads; add --json for raw JSON.
17-import { readFileSync } from "node:fs";
18-
19-const argv = process.argv.slice(2);
20-const command = argv[0];
